// Validate enrollment stage change
const event = $input.all()[0].json;

if (event.stage !== 'Enrolled') {
  throw new Error('Not an enrollment event');
}

return [{
  contactId: event.contact.id,
  parentName: event.contact.firstName + ' ' + event.contact.lastName,
  parentEmail: event.contact.email,
  parentPhone: event.contact.phone,
  childName: event.contact.childName,
  childAge: event.contact.childAge,
  swimLevel: event.contact.swimLevel || 'Beginner',
  enrollmentDate: new Date().toISOString().split('T')[0],
  timestamp: new Date().toISOString()
}];

